    match media.payload {
        MediaPayload::Structured { schema, json } => {
            assert_eq!(schema, "3d.mesh");
            assert!(!json.is_empty());
        }
        MediaPayload::Binary { .. } => panic!("expected a Structured payload"),
        MediaPayload::Intrinsic { .. } => panic!("expected a Structured payload"),
    }
}
